import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    strengths = [int(next(it)) for _ in range(n)]
    t = int(next(it))

    for _ in range(t):
        l = int(next(it)) - 1  # 0-indexed
        r = int(next(it)) - 1

        # Count how many ants have exactly (r-l) points
        count = 0

        for i in range(l, r + 1):
            s = strengths[i]
            points = 0

            for j in range(l, r + 1):
                if i != j and strengths[j] % s == 0:
                    points += 1

            if points == (r - l):
                count += 1

        print((r - l + 1) - count)

if __name__ == "__main__":
    solve()
"}

