def solve():
    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())

        # If k is larger than the number of almost sorted permutations, output -1
        if k > 2 ** (n - 1):
            print(-1)
        else:
            # Start with the identity permutation
            perm = list(range(1, n + 1))

            # For each position from n-1 down to 1
            for i in range(n - 1, 0, -1):
                # If k is odd, keep the current order
                if k % 2 == 1:
                    pass  # No swap
                else:
                    # Swap the current element with the previous one
                    perm[i - 1], perm[i] = perm[i], perm[i - 1]

                # Move to the next level of the binary tree
                k //= 2

            print(' '.join(map(str, perm)))

solve()
