def compute_grundy(m, k):
    # Compute Grundy numbers for all lengths from k to m
    grundy = [0] * (m + 1)

    for length in range(k, m + 1):
        # Check if this length can be split
        can_split = False
        reachable = set()

        # Try all possible splits
        for t in range(2, length + 1):
            if length % t == 0:
                part_length = length // t
                if part_length >= k:
                    can_split = True

                    # Compute the resulting Grundy number
                    if t % 2 == 0:
                        # Even number of parts, XOR of t copies of grundy[part_length] is 0
                        reachable.add(0)
                    else:
                        # Odd number of parts, XOR of t copies of grundy[part_length] is grundy[part_length]
                        reachable.add(grundy[part_length])

        if not can_split:
            grundy[length] = 0
        else:
            # Compute mex
            mex = 0
            while mex in reachable:
                mex += 1
            grundy[length] = mex

    return grundy

def solve():
    n, m, k = map(int, input().split())

    # Compute Grundy numbers
    grundy = compute_grundy(m, k)

    # Determine overall Grundy number
    if n % 2 == 1:
        overall_grundy = grundy[m]
    else:
        overall_grundy = 0

    # Determine winner
    if overall_grundy == 1:
        print("Timur")
    else:
        print("Marsel")

solve()
"}

