count_2 = a.count(2)

# Strategy: start with 2, then add 1, then add as many 2s as possible, then add 1s
if count_2 > 0:
    # Start with 2
    result = [2]
    count_2 -= 1

    # Add 1
    if count_1 > 0:
        result.append(1)
        count_1 -= 1

    # Add as many 2s as possible
    while count_2 > 0:
        result.append(2)
        count_2 -= 1

    # Add remaining 1s
    if count_1 > 0:
        result.extend([1] * count_1)
else:
    # All are 1s, just output them
    result = a

print(' '.join(map(str, result)))
