from collections import deque

def bpm(u, visited, match_to, adj):
    """Bipartite matching using DFS"""
    visited[u] = True
    for v in adj[u]:
        if match_to[v] == -1 or (not visited[match_to[v]] and bpm(match_to[v], visited, match_to, adj)):
            match_to[v] = u
            return True
    return False

def solve():
    n, m = map(int, input().split())
    w = list(map(int, input().split()))

    # Build adjacency list for bipartite graph
    adj = [[] for _ in range(m + 1)]
    for i in range(1, m + 1):
        x, y = map(int, input().split())
        adj[i].append(x)
        adj[i].append(y)

    # Find maximum matching
    match_to = [-1] * (n + 1)  # match_to[food] = friend
    result = 0

    for u in range(1, m + 1):
        visited = [False] * (n + 1)
        if bpm(u, visited, match_to, adj):
            result += 1

    if result == m:
        print("ALIVE")
        # Reconstruct the order
        order = [0] * m
        for v in range(1, n + 1):
            if match_to[v] != -1:
                order[match_to[v] - 1] = v

        # Print the order
        for i in range(m):
            print(order[i], end=' ')
        print()
    else:
        print("DEAD")

solve()
