def solve():
    import sys

    words = []
    N = int(sys.stdin.readline())
    Q = int(sys.stdin.readline())

    for _ in range(N):
        word = sys.stdin.readline().strip()
        words.append(word)

    for _ in range(Q):
        line = sys.stdin.readline().strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 2:
            continue
        prefix = parts[0]
        suffix = parts[1]

        count = 0
        for word in words:
            if word.startswith(prefix) and word.endswith(suffix):
                count += 1
        print(count)

if __name__ == "__main__":
    solve()
