    if word == "":
        non_number_words.append(word)
        continue

    # Check if it's a valid nonnegative integer without leading zeroes
    if word.isdigit():
        if len(word) == 1 or (len(word) > 1 and word[0] != '0'):
            number_words.append(word)
        else:
            non_number_words.append(word)
    else:
        non_number_words.append(word)

