def find_cycle(graph, n):
    """Find a directed cycle in the graph using DFS"""
    visited = [False] * (n + 1)
    recursion_stack = [False] * (n + 1)
    cycle = []

    def dfs(v, path):
        if recursion_stack[v]:
            # Found a cycle
            idx = path.index(v)
            cycle.extend(path[idx:])
            return True

        if visited[v]:
            return False

        visited[v] = True
        recursion_stack[v] = True
        path.append(v)

        for neighbor in graph[v]:
            if dfs(neighbor, path):
                return True

        recursion_stack[v] = False
        path.pop()
        return False

    for v in range(1, n + 1):
        if not visited[v]:
            if dfs(v, []):
                return cycle

    return None

# Read input
n, m = map(int, input().split())
graph = [[] for _ in range(n + 1)]
for _ in range(m):
    a, b = map(int, input().split())
    graph[a].append(b)

# Find a cycle
cycle = find_cycle(graph, n)

if cycle:
    print(len(cycle))
    for v in cycle:
        print(v)
else:
    print(-1)
