def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        # Convert to parities (0 for even, 1 for odd)
        parities = [x % 2 for x in a]

        swaps = 0
        i = 0
        while i < n - 1:
            # Check if current and next have same parity
            if parities[i] == parities[i + 1]:
                # Try to fix by swapping with next element
                if i + 2 < n and parities[i + 2] != parities[i + 1]:
                    # Swap i+1 with i+2
                    parities[i + 1], parities[i + 2] = parities[i + 2], parities[i + 1]
                    swaps += 1
                    i += 1  # Move to next position after swap
                else:
                    # Try to fix by swapping with previous element
                    if i - 1 >= 0 and parities[i - 1] != parities[i]:
                        # Swap i with i-1
                        parities[i - 1], parities[i] = parities[i], parities[i - 1]
                        swaps += 1
                        i -= 1  # Move to previous position after swap
                    else:
                        # Impossible to fix
                        print(-1)
                        break
            else:
                i += 1
        else:
            # Check if final array is valid
            valid = True
            for j in range(n - 1):
                if parities[j] == parities[j + 1]:
                    valid = False
                    break
