def can_form_suffix(suffix_part):
    """Check if suffix_part can be formed by appending suffixes of length 2 or 3 without repeating consecutively"""
    n = len(suffix_part)

    # Try all possible root lengths
    for root_length in range(5, n - 1 + 1):
        suffix_part = s[root_length:]

        # Check if we can form this suffix_part
        # Use backtracking to try all possibilities
        def backtrack(pos, last_suffix):
            if pos == len(suffix_part):
                return True

            # Try appending a suffix of length 2
            if pos + 2 <= len(suffix_part):
                new_suffix = suffix_part[pos:pos+2]
                if new_suffix != last_suffix:
                    if backtrack(pos + 2, new_suffix):
                        return True

            # Try appending a suffix of length 3
            if pos + 3 <= len(suffix_part):
                new_suffix = suffix_part[pos:pos+3]
                if new_suffix != last_suffix:
                    if backtrack(pos + 3, new_suffix):
                        return True

            return False

        if backtrack(0, None):
            # If we can form it, collect all suffixes
            suffixes = set()

            # Try all possible ways to form it
            def collect_suffixes(pos, last_suffix, current_suffixes):
                if pos == len(suffix_part):
                    return current_suffixes.copy()

                # Try appending a suffix of length 2
                if pos + 2 <= len(suffix_part):
                    new_suffix = suffix_part[pos:pos+2]
                    if new_suffix != last_suffix:
                        new_suffixes = current_suffixes.copy()
                        new_suffixes.add(new_suffix)
                        result = collect_suffixes(pos + 2, new_suffix, new_suffixes)
                        if result:
                            return result

                # Try appending a suffix of length 3
                if pos + 3 <= len(suffix_part):
                    new_suffix = suffix_part[pos:pos+3]
                    if new_suffix != last_suffix:
                        new_suffixes = current_suffixes.copy()
                        new_suffixes.add(new_suffix)
                        result = collect_suffixes(pos + 3, new_suffix, new_suffixes)
                        if result:
                            return result

                return None

            all_suffixes = collect_suffixes(0, None, set())
            if all_suffixes:
                return all_suffixes

    return set()

s = input().strip()
