    """Cross product of vectors OA and OB"""
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def dot(o, a, b):
    """Dot product of vectors OA and OB"""
    return (a[0] - o[0]) * (b[0] - o[0]) + (a[1] - o[1]) * (b[1] - o[1])

def dist_sq(a, b):
    """Squared distance between points a and b"""
    return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

def is_point_on_segment(p, a, b):
    """Check if point p lies on segment ab"""
    # Check if p is collinear with a and b
    if abs(cross(a, b, p)) > 1e-9:
        return False

    # Check if p is within the bounding box of a and b
    if min(a[0], b[0]) - 1e-9 <= p[0] <= max(a[0], b[0]) + 1e-9 and 
       min(a[1], b[1]) - 1e-9 <= p[1] <= max(a[1], b[1]) + 1e-9:
        return True
    return False

def is_proportional(p, a, b, ratio):
    """Check if point p divides segment ab in ratio (AP/AB) >= ratio or <= 1-ratio"""
    # Check if p is collinear with a and b
    if abs(cross(a, b, p)) > 1e-9:
        return False

    # Check if p is within the segment
