import sys

def modinv(a, m):
    """Compute modular inverse using Fermat's little theorem"""
    return pow(a, m - 2, m)

def comb(n, k, mod):
    """Compute combination C(n, k) modulo mod"""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1

    # Compute C(n, k) = n! / (k! * (n-k)!) mod mod
    # We can compute factorials and use modular inverse

    # Precompute factorials up to n
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i-1] * i % mod

    # Compute inverse factorials
    inv_fact = [1] * (n + 1)
    inv_fact[n] = modinv(fact[n], mod)
    for i in range(n-1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % mod

    return fact[n] * inv_fact[k] % mod * inv_fact[n - k] % mod


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    N = int(data[0])
