def modinv(a, m):
    """Modular inverse using Fermat's little theorem"""
    return pow(a, m-2, m)

# Precompute factorials and inverse factorials modulo 10^9+7
MOD = 10**9 + 7
MAX = 10**5 + 10

# Precompute factorials
fact = [1] * (MAX)
for i in range(1, MAX):
    fact[i] = fact[i-1] * i % MOD

# Precompute inverse factorials
inv_fact = [1] * (MAX)
inv_fact[MAX-1] = modinv(fact[MAX-1], MOD)
for i in range(MAX-2, -1, -1):
    inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

# Combination function
def comb(n, k):
    """C(n, k) modulo MOD"""
    if n < 0 or k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

# Precompute Möbius function
mu = [1] * (MAX)
min_prime = [0] * (MAX)
for i in range(2, MAX):
    if min_prime[i] == 0:
        min_prime[i] = i
        for j in range(i*i, MAX, i):
            if min_prime[j] == 0:
                min_prime[j] = i

for i in range(2, MAX):
    if min_prime[i] == i:
        # i is prime
        mu[i] = -1
    else:
        # i has a prime factor
        p = min_prime[i]
        if i // p % p == 0:
            # i has at least two factors of p
            mu[i] = 0
        else:
            # i has exactly one factor of p
            mu[i] = mu[i // p]

q = int(input())
for _ in range(q):
    n, f = map(int, input().split())
    ans = 0
    for k in range(1, n + 1):
        if n % k == 0:
            c = comb((n // k) - 1, f - 1)
            ans = (ans + mu[k] * c) % MOD
    print(ans)
